        "<strong>Dictionary (Easton's).</strong> <strong>ABISHAG</strong> father of (i.e., “given to”) error, a young woman of Shunem, distinguished for her beauty. She was chosen to minister to David in his old age. She became his wife (1 Kings 1:3,4,15). After David’s death Adonijah persuaded Bathsheba, Solomon’s mother, to entreat the king to permit him to marry Abishag. Solomon suspected in this request an aspiration to the throne, and therefore caused him to be put to death (1 Kings 2:17-25). <em>[Reviewer: condense Easton's entry as needed.]</em>",
