        "Hebrew",
        """<strong>Anointed at Gihon.</strong> The Gihon spring was Jerusalem’s primary water source and a place of public gathering at the city’s east slope. Kings anointed there are visibly endorsed by the city’s lifeblood. Solomon’s anointing at Gihon, rather than at the palace, deliberately stages legitimacy in front of the populace — a counter-move against Adonijah’s private banquet at En-Rogel.""",
        "User original",
