        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ETHAN</strong> firm. (1.) “The Ezrahite,” distinguished for his wisdom (1 Kings 4:31). He is named as the author of the 89th Psalm. He was of the tribe of Levi. (2.) A Levite of the family of Merari, one of the leaders of the temple music (1 Chronicles 6:44; 15:17, 19). He was probably the same as Jeduthun. He is supposed by some to be the same also as (1). <em>[Reviewer: condense Easton's entry as needed.]</em>",
