        "comm",
        "Note",
        "Note",
        """<strong>Hiram of Tyre.</strong> Hiram I of Tyre (c. 970-936 BCE) is independently attested in Tyrian king lists preserved by Josephus. The treaty alliance places Israel within a Phoenician trade network; Phoenician craftsmanship and cedar will dominate the temple’s design. The economic asymmetry is striking — Israel pays in agricultural produce for Phoenician technical goods (5:11).""",
