    (
        6,
        23,
        "",
        "two cherubim of olive wood",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>The cherubim.</strong> Two olive-wood cherubim, fifteen feet tall, gold-plated, with outstretched wings spanning the holy of holies. Cherubim in ANE iconography are composite guardian figures — winged hybrid beasts (the Akkadian <em>kāribu</em>) flanking thrones and gateways. Solomon’s cherubim function as Yahweh’s throne-guardians, framing the empty space above the ark where Yahweh is enthroned (Ps 80:1, 99:1). The temple thus participates in widely shared ANE divine-throne architecture even as it insists on the absence of any divine image — only the empty throne.",
        "User original",
    ),
