        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BUL</strong> rainy, the eighth ecclesiastical month of the year (1 Kings 6:38), and the second month of the civil year; later called Marchesvan (q.v.). (See MONTH.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
