        "<strong>Dictionary (Easton's).</strong> <strong>MARCHESHVAN</strong> the post-biblical name of the month which was the eighth of the sacred and the second of the civil year of the Jews. It began with the new moon of our November. It is once called Bul (1 Kings 6:38). Assyrian, Arah Samna, “eighth month,” <em>[Reviewer: condense Easton's entry as needed.]</em>",
