        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BAALBEC</strong> called by the Greeks Heliopolis i.e., “the city of the sun”, because of its famous Temple of the Sun, has by some been supposed to be Solomon’s “house of the forest of Lebanon” (1 Kings 7:2; 10:17; 2 Chronicles 9:16); by others it is identified with Baal-gad (q.v.). It was a city of Coele-Syria, on the lowest declivity of Anti-Libanus, about 42 miles north-west of Damascus. It was one of the most splendid of Syrian cities, existing from a remote antiquity. After sustaining… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
