        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>CEILING</strong> the covering (1 Kings 7:3,7) of the inside roof and walls of a house with planks of wood (2 Chronicles 3:5; Jeremiah 22:14). Ceilings were sometimes adorned with various ornaments in stucco, gold, silver, gems, and ivory. The ceilings of the temple and of Solomon’s palace are described 1 Kings 6:9, 15; 7:3; 2 Chronicles 3:5,9. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
