        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>PORCH</strong> , SOLOMON’S a colonnade on the east of the temple, so called from a tradition that it was a relic of Solomon’s temple left standing after the destruction of Jerusalem by the Babylonians. (Comp. 1 Kings 7:6.) The word “porch” is in the New Testament the rendering of three different Greek words: (1.) Stoa, meaning a portico or veranda (John 5:2; 10:23; Acts 3:11; 5:12). (2.) Pulon, a gateway (Matthew 26:71). (3.) Proaulion, the entrance to the inner court (Mark 14:68). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
