        "<strong>Dictionary (Easton's).</strong> <strong>JACHIN AND BOAZ</strong> the names of two brazen columns set up in Solomon’s temple (1 Kings 7:15-22). Each was eighteen cubits high and twelve in circumference (Jeremiah 52:21, 23; 1 Kings 7:17-21). They had doubtless a symbolical import. <em>[Reviewer: condense Easton's entry as needed.]</em>",
