        "<strong>Dictionary (Easton's).</strong> <strong>LILY T</strong> he Hebrew name shushan or shoshan, i.e., “whiteness”, was used as the general name of several plants common to Syria, such as the tulip, iris, anemone, gladiolus, ranunculus, etc. Some interpret it, with much probability, as denoting in the Old Testament the water-lily (Nymphoea lotus of Linn.), or lotus (Cant. 2:1, 2; 2:16; 4:5; 5:13; 6:2, 3; 7:2). “Its flowers are large, and they are of a white colour, with streaks of pink. They supplied models for the ornaments of the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
