        "<strong>Dictionary (Easton's).</strong> <strong>SEA</strong> , THE MOLTEN the great laver made by Solomon for the use of the priests in the temple, described in 1 Kings 7:23-26; 2 Chronicles 4:2-5. It stood in the south-eastern corner of the inner court. It was 5 cubits high, 10 in diameter from brim to brim, and 30 in circumference. It was placed on the backs of twelve oxen, standing with their faces outward. It was capable of containing two or three thousand baths of water (comp. 2 Chronicles 4:5), which was originally supplied by… <em>[Reviewer: condense Easton's entry as needed.]</em>",
