        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ETHANIM</strong> the month of gifts, i.e., of vintage offerings; called Tisri after the Exile; corresponding to part of September and October. It was the first month of the civil year, and the seventh of the sacred year (1 Kings 8:2). <em>[Reviewer: condense Easton's entry as needed.]</em>",
