    (
        8,
        11,
        "",
        "the glory of Yahweh filled the house",
        "comm",
        "Note",
        "Note",
        """<strong>The kavod fills the temple.</strong> The Hebrew <em>kavod</em> ("glory," "weight") is the visible-perceivable presence of Yahweh, paralleled in Exod 40:34–35 (the tabernacle) and Ezek 10–11 (where the kavod departs from this same temple before its destruction). The cloud-filling scene establishes the temple as legitimate dwelling-place; Ezekiel’s departure scene establishes that legitimacy as forfeited. Both scenes use the same vocabulary deliberately. The Christian gospel of John intentionally echoes this idiom — "the Word became flesh and tabernacled among us, and we beheld his glory" (John 1:14) — claiming the same divine indwelling for Christ.""",
        "User original",
    ),
