        "<strong>Dictionary (Easton's).</strong> <strong>CATERPILLAR</strong> the consumer. Used in the Old Testament (1 Kings 8:37; 2 Chronicles 6:28; Psalm 78:46; Isaiah 33:4) as the translation of a word (hasil) the root of which means “to devour” or “consume,” and which is used also with reference to the locust in Deuteronomy 28:38. It may have been a species of locust, or the name of one of the transformations through which the locust passes, locust-grub. It is also found (Psalm 105:34; Jeremiah 51:14, 27; R.V., “cankerworm”) as the rendering of… <em>[Reviewer: condense Easton's entry as needed.]</em>",
