        "Note",
        "Note",
        "<strong>Queen of Sheba.</strong> Sheba is most plausibly south Arabia (modern Yemen), though Ethiopian tradition (the Kebra Nagast) identifies her as Makeda, ancestress of the Solomonic dynasty — a tradition central to Ethiopian Christian identity. No specific historical queen of Sheba is attested in Sabaean sources, but trade between Israel and south Arabia along the incense route is well documented archaeologically.",
        "User paraphrase; references Kebra Nagast",
