        "<strong>Dictionary (Easton's).</strong> <strong>ALMUG</strong> (1 Kings 10:11, 12) = algum (2 Chronicles 2:8; 9:10, 11), in the Hebrew occurring only in the plural almuggim (indicating that the wood was brought in planks), the name of a wood brought from Ophir to be used in the building of the temple, and for other purposes. Some suppose it to have been the white sandal-wood of India, the Santalum album of botanists, a native of the mountainous parts of the Malabar coasts. It is a fragrant wood, and is used in China for incense in… <em>[Reviewer: condense Easton's entry as needed.]</em>",
