        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>REZON</strong> prince, son of Eliadah. Abandoning the service of Hadadezer, the king of Zobah, on the occasion of his being defeated by David, he became the “captain over a band” of marauders, and took Damascus, and became king of Syria (1 Kings 11:23-25; 2 Samuel 8:3-8). For centuries after this the Syrians were the foes of Israel. He “became an adversary to Israel all the days of Solomon.” <em>[Reviewer: condense Easton's entry as needed.]</em>",
