        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JEROBOAM</strong> increase of the people. (1.) The son of Nebat (1 Kings 11:26-39), “an Ephrathite,” the first king of the ten tribes, over whom he reigned twenty-two years (B.C. 976-945). He was the son of a widow of Zereda, and while still young was promoted by Solomon to be chief superintendent of the “burnden”, i.e., of the bands of forced labourers. Influenced by the words of the prophet Ahijah, he began to form conspiracies with the view of becoming king of the ten tribes; but these… <em>[Reviewer: condense Easton's entry as needed.]</em>",
