    (
        12,
        11,
        "",
        "I will chastise you with scorpions",
        "comm",
        "Note",
        "Note",
        """<strong>Rehoboam’s threat.</strong> "Scorpions" likely refers to a scourge with knotted barbs designed to tear flesh. Rehoboam’s reply to the northern tribes’ grievance over Solomonic forced labor is one of the great folly-set-pieces of scripture: he rejects the elder counsel, takes the young men’s advice, and triples down on the corvée. The kingdom splits the next verse. The narrative pattern — wise old advice rejected for young flattery — appears again in Greek tragedy and Shakespeare; the biblical version reads as a foundational political parable. The forced labor of the temple-building era was literally building toward this fracture.""",
        "User original",
    ),
