        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>SCOURGING</strong> (1 Kings 12:11). Variously administered. In no case were the stripes to exceed forty (Deuteronomy 25:3; comp. 2 Corinthians 11:24). In the time of the apostles, in consequence of the passing of what was called the Porcian law, no Roman citizen could be scourged in any case (Acts 16:22-37). (See BASTINADO.) In the scourging of our Lord (Matthew 27:26; Mark 15:15) the words of prophecy (Isaiah 53:5) were fulfilled. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
