        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AVEN</strong> nothingness; vanity. (1.) Hosea speaks of the “high places of Aven” (10:8), by which he means Bethel. He also calls it Beth-aven, i.e., “the house of vanity” (4:15), on account of the golden calves Jeroboam had set up there (1 Kings 12:28). (2.) Translated by the LXX. “On” in Ezekiel 30:17. The Egyptian Heliopolis or city of On (q.v.). (3.) In Amos 1:5 it denotes the Syrian Heliopolis, the modern Baalbec. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
