        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HIGH PLACE</strong> an eminence, natural or artificial, where worship by sacrifice or offerings was made (1 Kings 13:32; 2 Kings 17:29). The first altar after the Flood was built on a mountain (Genesis 8:20). Abraham also built an altar on a mountain (12:7, 8). It was on a mountain in Gilead that Laban and Jacob offered sacrifices (31:54). After the Israelites entered the Promised Land they were strictly enjoined to overthrow the high places of the Canaanites (Exodus 34:13; Deuteronomy 7:5;… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
