        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>NAAMAH</strong> the beautiful. (1.) The daughter of Lamech and Zillah (Genesis 4: 22). (2.) The daughter of the king of Ammon, one of the wives of Solomon, the only one who appears to have borne him a son, viz., Rehoboam (1 Kings 14:21, 31). (3.) A city in the plain of Judah (Joshua 15:41), supposed by some to be identified with Na’aneh, some 5 miles south-east of Makkedah. <em>[Reviewer: condense Easton's entry as needed.]</em>",
