        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ASA</strong> physician, son of Abijah and grandson of Rehoboam, was the third king of Judah. He was zealous in maintaining the true worship of God, and in rooting all idolatry, with its accompanying immoralities, out of the land (1 Kings 15:8-14). The Lord gave him and his land rest and prosperity. It is recorded of him, however, that in his old age, when afflicted, he “sought not to the Lord, but to the physicians” (comp. Jeremiah 17:5). He died in the forty-first year of his reign,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
