        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>KEDRON</strong> the valley, now quite narrow, between the Mount of Olives and Mount Moriah. The upper part of it is called the Valley of Jehoshaphat. The LXX., in 1 Kings 15:13, translate “of the cedar.” The word means “black,” and may refer to the colour of the water or the gloom of the ravine, or the black green of the cedars which grew there. John 18:1, “Cedron,” only here in New Testament. (See KIDRON.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
