        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BEN-HADAD</strong> the standing title of the Syrian kings, meaning “the son of Hadad.” (See HADADEZER.) (1.) The king of Syria whom Asa, king of Judah, employed to invade Israel (1 Kings 15:18). (2.) Son of the preceding, also king of Syria. He was long engaged in war against Israel. He was murdered probably by Hazael, by whom he was succeeded (2 Kings 8:7-15), after a reign of some thirty years. (3.) King of Damascus, and successor of his father Hazael on the throne of Syria (2 Kings 13:3,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
