        "<strong>Dictionary (Easton's).</strong> <strong>SAMARIA</strong> a watch-mountain or a watch-tower. In the heart of the mountains of Israel, a few miles north-west of Shechem, stands the “hill of Shomeron,” a solitary mountain, a great “mamelon.” It is an oblong hill, with steep but not inaccessible sides, and a long flat top. Omri, the king of Israel, purchased this hill from Shemer its owner for two talents of silver, and built on its broad summit the city to which he gave the name of “Shomeron”, i.e., Samaria, as the new capital of his… <em>[Reviewer: condense Easton's entry as needed.]</em>",
