        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JEZEBEL</strong> chaste, the daughter of Ethbaal, the king of the Zidonians, and the wife of Ahab, the king of Israel (1 Kings 16:31). This was the “first time that a king of Israel had allied himself by marriage with a heathen princess; and the alliance was in this case of a peculiarly disastrous kind. Jezebel has stamped her name on history as the representative of all that is designing, crafty, malicious, revengeful, and cruel. She is the first great instigator of persecution against the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
