        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>TISHBITE E</strong> lijah the prophet was thus named (1 Kings 17:1; 21:17, 28, etc.). In 1 Kings 17:1 the word rendered “inhabitants” is in the original the same as that rendered “Tishbite,” hence that verse may be read as in the LXX., “Elijah the Tishbite of Tishbi in Gilead.” Some interpret this word as meaning “stranger,” and read the verse, “Elijah the stranger from among the strangers in Gilead.” This designation is probably given to the prophet as denoting that his birthplace was Tishbi,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
