        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>LEEK</strong> (Hebrews hatsir; the Allium porrum), rendered “grass” in 1 Kings 18:5, 2 Kings 19:26, Job 40:15, etc.; “herb” in Job 8:12; “hay” in Proverbs 27:25, and Isaiah 15:6; “leeks” only in Numbers 11:5. This Hebrew word seems to denote in this last passage simply herbs, such as lettuce or savoury herbs cooked as kitchen vegetables, and not necessarily what are now called leeks. The leek was a favourite vegetable in Egypt, and is still largely cultivated there and in Palestine. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
