        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>KISHON</strong> winding, a winter torrent of Central Palestine, which rises about the roots of Tabor and Gilboa, and passing in a northerly direction through the plains of Esdraelon and Acre, falls into the Mediterranean at the north-eastern corner of the bay of Acre, at the foot of Carmel. It is the drain by which the waters of the plain of Esdraelon and of the mountains that surround it find their way to the sea. It bears the modern name of Nahr el-Mokattah, i.e., “the river of slaughter”… <em>[Reviewer: condense Easton's entry as needed.]</em>",
