        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JUNIPER</strong> (Hebrews rothem), called by the Arabs retem, and known as Spanish broom; ranked under the genus genista. It is a desert shrub, and abounds in many parts of Palestine. In the account of his journey from Akabah to Jerusalem, Dr. Robinson says: “This is the largest and most conspicuous shrub of these deserts, growing thickly in the water-courses and valleys. Our Arabs always selected the place of encampment, if possible, in a spot where it grew, in order to be sheltered by it… <em>[Reviewer: condense Easton's entry as needed.]</em>",
