        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MANTLE</strong> (1.) Hebrews ‘addereth, a large over-garment. This word is used of Elijah’s mantle (1 Kings 19:13, 19; 2 Kings 2:8, 13, etc.), which was probably a sheepskin. It appears to have been his only garment, a strip of skin or leather binding it to his loins. ’Addereth twice occurs with the epithet “hairy” (Genesis 25:25; Zechariah 13:4, R.V.). It is the word denoting the “goodly Babylonish garment” which Achan coveted (Joshua 7:21). (2.) Hebrews me’il, frequently applied to the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
