        "<strong>Dictionary (Easton's).</strong> <strong>HAZAEL</strong> whom God beholds, an officer of Ben-hadad II., king of Syria, who ultimately came to the throne, according to the word of the Lord to Elijah (1 Kings 19:15), after he had put the king to death (2 Kings 8:15). His interview with Elisha is mentioned in 2 Kings 8. The Assyrians soon after his accession to the throne came against him and defeated him with very great loss; and three years afterwards again invaded Syria, but on this occasion Hazael submitted to them. He then… <em>[Reviewer: condense Easton's entry as needed.]</em>",
