        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ABEL-MEHOLAH</strong> meadow of dancing, or the dancing-meadow, the birth-place and residence of the prophet Elisha, not far from Beth-shean (1 Kings 4:12), in the tribe of Issachar, near where the Wady el-Maleh emerges into the valley of the Jordan, “the rich meadow-land which extends about 4 miles south of Beth-shean; moist and luxuriant.” Here Elisha was found at his plough by Elijah on his return up the Jordan valley from Horeb (1 Kings 19:16). It is now called ‘Ain Helweh. <em>[Reviewer: condense Easton's entry as needed.]</em>",
