        "<strong>Dictionary (Easton's).</strong> <strong>ELISHA G</strong> od his salvation, the son of Shaphat of Abel-meholah, who became the attendant and disciple of Elijah (1 Kings 19:16-19). His name first occurs in the command given to Elijah to anoint him as his successor (1 Kings 19:16). This was the only one of the three commands then given to Elijah which he accomplished. On his way from Sinai to Damascus he found Elisha at his native place engaged in the labours of the field, ploughing with twelve yoke of oxen. He went over to him,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
