    (
        21,
        3,
        "",
        "inheritance of my fathers",
        "comm",
        "Note",
        "Note",
        """<strong>Naboth’s vineyard.</strong> Naboth refuses to sell because the land is <em>naḥalah</em> — ancestral inheritance, inalienable in principle (Lev 25:23, Num 36:7). The episode is the OT’s clearest illustration of the conflict between covenantal land-tenure (where land belongs to Yahweh and is held in trust by family lines) and royal-acquisitive power. Ahab’s sulking is less moral confusion than royal frustration at the limits of his authority; Jezebel’s solution — judicial murder via false witnesses — is foreign-monarchical politics imposed on Israelite legal structure. Elijah’s confrontation in 21:19 supplies the moral indictment.""",
        "User original",
    ),
