        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MICAIAH</strong> who is like Jehovah?, the son of Imlah, a faithful prophet of Samaria (1 Kings 22:8-28). Three years after the great battle with Ben-hadad (20:29-34), Ahab proposed to Jehoshaphat, king of Judah, that they should go up against Ramoth-Gilead to do battle again with Ben-hadad. Jehoshaphat agreed, but suggested that inquiry should be first made “at the word of Jehovah.” Ahab’s prophets approved of the expedition; but Jehoshaphat, still dissatisfied, asked if there was no other… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
