        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AMON</strong> builder. (1.) The governor of Samaria in the time of Ahab. The prophet Micaiah was committed to his custody (1 Kings 22:26; 2 Chronicles 18:25). (2.) The son of Manasseh, and fourteenth king of Judah. He restored idolatry, and set up the images which his father had cast down. Zephaniah (1:4; 3:4, 11) refers to the moral depravity prevailing in this king’s reign. He was assassinated (2 Kings 21:18-26: 2 Chronicles 33:20-25) by his own servants, who conspired against him. (3.)… <em>[Reviewer: condense Easton's entry as needed.]</em>",
