        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MICAH</strong> , BOOK OF the sixth in order of the so-called minor prophets. The superscription to this book states that the prophet exercised his office in the reigns of Jotham, Ahaz, and Hezekiah. If we reckon from the beginning of Jotham’s reign to the end of Hezekiah’s (B.C. 759-698), then he ministered for about fifty-nine years; but if we reckon from the death of Jotham to the accession of Hezekiah (B.C. 743-726), his ministry lasted only sixteen years. It has been noticed as… <em>[Reviewer: condense Easton's entry as needed.]</em>",
