    (
        22,
        34,
        "",
        "a certain man drew his bow at random",
        "comm",
        "Note",
        "Note",
        """<strong>The arrow at random.</strong> An unnamed Aramean archer, drawing without aim, hits Ahab through a gap in his armor. The verse is one of scripture’s most pointed assertions of providential agency through apparent contingency: nothing is random in the narrator’s universe. Ahab dies fulfilling Elijah’s prophecy of 21:19 — dogs licking his blood at the pool of Samaria where the chariot is washed (22:38). The narrative seal closes a story arc spanning chapters 17–22, and concludes the Elijah cycle’s major prophetic vindication.""",
        "User original",
    ),
    (
        1,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Abishag and the succession crisis.</strong> David’s frailty opens the book on a kingdom in transition. Abishag’s role is functionally political — proximity to the dying king is a marker of access to power. Her presence sets up Adonijah’s later request (2:13-25), in which asking for the king’s last consort reads as a claim on the throne itself, echoing the convention reflected in 2 Sam 16:21-22.""",
        "User original",
    ),
    (
        1,
        5,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Adonijah’s coup.</strong> Adonijah is the eldest surviving son after Amnon, Absalom, and Chileab. By Near Eastern primogeniture he is the natural heir, and his support base — Joab the long-time general and Abiathar the priest — represents the old guard from David’s wilderness years. The opposing faction (Nathan, Zadok, Benaiah) belongs to David’s later, Jerusalem-based establishment. The coup narrative is, at one level, a struggle between two halves of David’s career.""",
        "User original",
    ),
    (
        2,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>David’s deathbed charge.</strong> Verses 2-4 give pious Deuteronomistic counsel; verses 5-9 deliver a vendetta list (Joab, Shimei, the sons of Barzillai). The juxtaposition is unflinching, and the editor lets it stand without softening. This dual character — covenant fidelity yoked to political ruthlessness — is part of the canonical portrait of David.""",
        "User original",
    ),
    (
        2,
        26,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>End of Eli’s house.</strong> Abiathar’s banishment to Anathoth fulfills the curse on Eli’s house pronounced in 1 Sam 2:30-36. Centuries of priestly lineage end in a single political maneuver. The narrator notes the fulfillment explicitly in v. 27, an unusually direct cross-reference signalling Deuteronomistic editorial framing.""",
        "User original",
    ),
    (
        3,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Marriage to Pharaoh’s daughter.</strong> First mention of Solomon’s foreign marriages, foreshadowing the apostasy of ch. 11. Egyptian sources do not record any pharaoh giving a daughter to a foreign king during this period — Egyptian princesses were almost never sent abroad — so historians have long debated the report’s literal accuracy. Some propose she was a minor royal woman; others read the marriage as schematic, lending Solomon international stature.""",
        "User original",
    ),
    (
        3,
        16,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The two women and the child.</strong> The episode follows a wisdom-tale type widely paralleled across cultures (Indian, Chinese, and later Talmudic versions exist). Its placement here showcases Solomon’s God-given discernment in concrete judicial form, fulfilling 3:9 (’an understanding heart to judge’).""",
        "User original",
    ),
    (
        4,
        32,
        "",
        "",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>Three thousand proverbs.</strong> Solomon is here cast as the patron of Israelite wisdom, paralleling figures such as the Egyptian sage Amenemope (whose Instruction shows verbal overlap with Proverbs 22:17-24:22) or Akkadian wisdom collections. The numbers are likely topical rather than literal; they assert Solomon’s place in an international wisdom tradition.",
        "User original",
    ),
    (
        5,
        13,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Forced labor.</strong> Solomon imposes a corvée on Israel itself, despite the Deuteronomistic ideal that such labor should fall on resident aliens (cf. Josh 9:23, Deut 20:11). This grievance becomes the proximate trigger of the kingdom’s split: Rehoboam’s refusal to lighten the yoke (ch 12) is foreshadowed here.""",
        "User original",
    ),
    (
        6,
        7,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>No iron tool.</strong> Echoes Exodus 20:25’s prohibition against iron tools on the altar. The temple is consecrated beyond ordinary construction; even the act of building must respect ritual purity. Stones are dressed off-site, then assembled in silence — a deliberate aesthetic of holiness.""",
        "User original",
    ),
    (
        7,
        13,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Hiram the craftsman.</strong> Distinct from King Hiram. This Hiram is half-Israelite (Naphtali) and half-Tyrian, suggesting an artisan diaspora and reflecting Phoenician metallurgical preeminence. Bronze-casting on this scale — pillars, sea, capitals — required techniques largely foreign to Iron Age inland Israel.""",
        "User original",
    ),
    (
        8,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Ark brought into the temple.</strong> The cloud filling the temple (vv. 10-11) consciously echoes Exodus 40:34-35 at the wilderness Tabernacle. Yahweh’s presence has migrated from desert to city. The narrator stages this as the climax of the entire conquest-monarchy arc: from Sinai through the wilderness, the conquest, the judges, and David’s wars — to a settled house for the Name.""",
        "User original",
    ),
    (
        9,
        6,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Conditional warning.</strong> The classic Deuteronomistic theology of exile-as-judgment, paralleling Deut 28-30. Yahweh’s presence in the temple is conditional on covenant fidelity. The temple itself can be ’cast out of my sight’ — anticipating 2 Kings 25’s destruction. The book’s editorial frame is thus visible already in this Solomonic high-water mark.""",
        "User original",
    ),
    (
        10,
        14,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Six hundred sixty-six talents.</strong> The ironic number anticipates Revelation 13:18, where it marks the Beast. Tarshish is variously identified — Tartessos in southern Spain, Sardinia, or a generic term for distant Phoenician trade. Solomon’s wealth here is meant to evoke not just prosperity but the dangerous excess that 11:1-13 will indict.""",
        "User original",
    ),
    (
        11,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Solomon’s apostasy.</strong> The theological pivot of the entire book. The 700 wives and 300 concubines are likely topical — the same hyperbolic numerical idiom found in Song of Songs 6:8 and across Near Eastern royal rhetoric. The point is that political alliance via marriage compromised cultic purity. Everything that follows — schism, exile, restoration — flows from this turning point.""",
        "User original",
    ),
    (
        11,
        29,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Ahijah’s torn cloak.</strong> Prophetic sign-acts physicalize divine speech (cf. Isa 20, Jer 19, Ezek 4). Ten pieces to Jeroboam, one to Rehoboam: Judah is the one, with Benjamin assumed alongside it (the ’two tribes’ counted as one). The remainder of the canonical Twelve are now consigned to a separate kingdom whose theological legitimacy will remain ambiguous.""",
        "User original",
    ),
    (
        12,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The schism at Shechem.</strong> Shechem, not Jerusalem, is the meeting site — already a sign of northern leverage. Rehoboam’s harshness is the proximate cause, but the deeper roots run to Solomon’s corvée labor (5:13-18). The kingdom split begins as a tax revolt and ends as a 200-year political division until 722 BCE.""",
        "User original",
    ),
    (
        12,
        25,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Jeroboam’s golden calves.</strong> The Deuteronomist condemns Jeroboam unforgivably for the bull-images at Bethel and Dan, repeating the verdict throughout Kings (’the sin of Jeroboam son of Nebat’). Some scholars argue the bulls may have functioned as pedestals for the invisible Yahweh — directly parallel to the cherubim throne in Jerusalem — and so were not idolatrous in original conception. The Deuteronomistic editor allows no such nuance.""",
        "User original",
    ),
    (
        13,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The man of God from Judah.</strong> A strange embedded narrative: a Judean prophet, a lying Bethel prophet, a lion that kills but does not eat. The chapter likely preserves an older oracle subsequently overlaid with a prediction (v. 2) of Josiah’s reform three centuries later. The episode is one of Kings’ most theologically unsettling — true and false prophecy are not always distinguishable in advance.""",
        "User original",
    ),
    (
        14,
        25,
        "",
        "",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>Shishak’s invasion.</strong> Pharaoh Shoshenq I (c. 945-924 BCE), founder of the Twenty-second Dynasty. The Karnak relief in his Bubastite Portal lists 154 conquered Palestinian cities, including many in Israel and Judah. This is one of the strongest synchronisms between biblical narrative and external Iron Age archaeology, securely placing Rehoboam’s reign in absolute chronology.",
        "User original",
    ),
    (
        15,
        11,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Asa’s reform.</strong> Asa’s removal of cult prostitutes and idols is the first reformist reign in Judah after the schism. The Deuteronomist’s evaluative formula (’he did what was right in Yahweh’s eyes’) becomes a fixed template for measuring kings; Asa is the first to receive it unequivocally.""",
        "User original",
    ),
    (
        16,
        23,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Omri.</strong> Twelve verses for one of the most powerful Israelite kings. For more than a century after his death, Assyrian inscriptions refer to the northern kingdom as bīt Ḫumri (’House of Omri’). The Mesha Stele (c. 840 BCE, Moabite) describes Omri’s hegemony over Moab. The Deuteronomist deliberately compresses his account, downplaying achievements that fall outside the cultic evaluation framework.""",
        "User original",
    ),
    (
        16,
        29,
        "",
        "",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>Ahab and Jezebel.</strong> The Sidonian alliance through Jezebel imports Tyrian Baal worship at the state level. The Tel Dan Aramaic inscription (c. 840 BCE) likely references Joram son of Ahab and ’Ahaziahu, king of the house of David’ — the earliest extra-biblical reference to David’s dynasty. The Omride dynasty’s archaeological footprint (Samaria’s monumental architecture) confirms its political weight.",
        "User original",
    ),
    (
        17,
        8,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The Sidonian widow.</strong> Zarephath sits in Phoenician territory — Jezebel’s home region. Elijah’s miraculous provision and resurrection of a foreign widow’s son will be cited by Jesus in Luke 4:26 as proof that God’s mercy reaches beyond ethnic Israel. The episode is a pointed counter to the localism Jezebel is importing in the opposite direction.""",
        "User original",
    ),
    (
        18,
        20,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Mt Carmel.</strong> Carmel sits on the border of Phoenicia and Israel — Baal’s home territory and Yahweh’s. The trial-by-fire is a public theological duel staged at the ritual frontier. The detail of Elijah dousing the altar with water (vv. 33-35) inverts the storm god’s element: Baal cannot light a fire on a wet altar, and Yahweh turns water into the fuel of his manifestation.""",
        "User original",
    ),
    (
        19,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The voice of thin silence.</strong> The Hebrew qol demamah daqqah is famously hard to translate — ’still small voice’ (KJV), ’gentle whisper’ (NIV), or more literally ’voice of fine silence.’ The point is the inversion of expected theophany: Yahweh is not in the wind, earthquake, or fire (the conventional storm-god repertoire) but in something delicate that comes after them. It is a deliberate counter-statement to Sinai (Exod 19) and to Baal.""",
        "User original",
    ),
    (
        19,
        19,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Elisha called.</strong> The mantle is transferable charisma; throwing it onto Elisha is a wordless calling. The ploughing detail — twelve yoke of oxen — marks Elisha as wealthy. He sacrifices the team, burns the equipment, and follows: there is no path back. The act echoes Jesus’ calling of disciples ’who left their nets’ (Mark 1:18).""",
        "User original",
    ),
    (
        21,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Naboth’s vineyard.</strong> Ancestral land was inalienable under Israelite law (Lev 25:23-28, Num 36:7). Naboth’s refusal is not stubbornness but covenant fidelity. Jezebel’s solution — false witness, judicial murder, royal seizure — violates four commandments at once. The episode crystallizes the prophetic critique of monarchy: kings who think they can rewrite Israel’s economic theology will face Yahweh’s word.""",
        "User original",
    ),
    (
        22,
        1,
        "",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>Micaiah ben Imlah.</strong> One of the OT’s most theologically daring scenes. Yahweh consciously commissions a ’lying spirit’ (vv. 19-23) to deceive Ahab toward his death. The text treats prophecy as a test of discernment, not just transmission — the four hundred court prophets speak truthfully about what they hear, but what they hear has been seeded with deception as judgment. The passage troubled later interpreters; the LXX softens some details, and rabbinic and Christian commentary developed elaborate theodicies.""",
        "User paraphrase; references LXX",
    ),
